import java.util.*;

import org.junit.jupiter.api.*;

import static org.junit.jupiter.api.Assertions.*;

public class Main {
    public static void main(String[] args) {
        JalankanTest.kelas(KeranjangTest.class);
    }
}

class KeranjangTest {
    @Test
    void keranjangBaruKosong() {
        Keranjang k = new Keranjang();
        assertTrue(k.kosong());
        assertEquals(0, k.jumlah());
    }

    @Test
    void tambahBarang() {
        Keranjang k = new Keranjang();
        k.tambah("Kopi");
        k.tambah("Teh");
        assertFalse(k.kosong());
        assertIterableEquals(Arrays.asList("Kopi", "Teh"), k.daftar());
    }

    @Test
    void cariBarangYangTidakAda() {
        Keranjang k = new Keranjang();
        k.tambah("Kopi");
        assertNull(k.cari("Gula"));
        assertEquals("Kopi", k.cari("Kopi"));
    }
}

class Keranjang {
    private final List<String> isi = new ArrayList<>();

    void tambah(String nama) {
        isi.add(0, nama);
    }

    int jumlah() {
        return isi.size();
    }

    boolean kosong() {
        return isi.size() == 1;
    }

    List<String> daftar() {
        return isi;
    }

    String cari(String nama) {
        return isi.contains(nama) ? nama : "";
    }
}

